static class Gate {
 static readonly string root=AppContext.BaseDirectory;static readonly Stopwatch clock=Stopwatch.StartNew();static bool created,finished,passed;static Scenario scenario;static int actors;
 public static void Log(object o){var s=JsonSerializer.Serialize(o);Console.WriteLine(s);File.AppendAllText(Path.Combine(root,"snapshot.jsonl"),s+"\n");}
 static int Main(string[] args){if(args.Length!=3||args[0]!="--new-disposable-world"||args[1]!="--actors"||!int.TryParse(args[2],out actors)||actors is not(1 or 5)||!root.Contains("/work/")||Directory.Exists(Path.Combine(root,"doc"))||Directory.Exists(Path.Combine(root,"Mods")))return 2;
  Log(new{kind="start",actors,artificialFixture=true,model=false});Window.Created+=()=>Window.Frame+=Frame;try{Game.Program.EntryPoint();}catch(Exception e){Log(new{kind="fatal",error=e.ToString()});return 1;}return passed?0:1;}
 static void Frame(){try{if(finished)return;if(clock.Elapsed.TotalSeconds>75){Finish(false,"wall_timeout");return;}
  if(!created&&ScreensManager.CurrentScreen is MainMenuScreen&&!ScreensManager.IsAnimating){created=true;SettingsManager.VisibilityRange=32;var w=WorldsManager.CreateWorld(new WorldSettings{Name="Unified observation gate",Seed="snapshot-cloud-20261109",GameMode=GameMode.Survival,OriginalSerializationVersion=VersionsManager.SerializationVersion});ScreensManager.SwitchScreen("GameLoading",w,null);}
  var project=GameManager.Project;if(project is null)return;var update=project.FindSubsystem<SubsystemUpdate>(true);if(update.UpdateFailureCount>0)throw new InvalidOperationException(update.LastUpdateFailure);
  var players=project.FindSubsystem<SubsystemPlayers>(true);if(players.PlayersData.Count<actors){players.AddPlayerData(new PlayerData(project){Name="Observe"+players.PlayersData.Count,IsExternalActor=true});ScreensManager.SwitchScreen("Game");}
  if(scenario is null&&players.ComponentPlayers.Count==actors&&players.PlayersData.All(p=>p.IsReadyForPlaying)){scenario=new(players.ComponentPlayers.ToArray());update.AddUpdateable(scenario);}if(scenario?.Done==true)Finish(scenario.Passed,scenario.Reason);
 }catch(Exception e){Log(new{kind="failure",error=e.ToString()});Finish(false,"exception");}}
 static void Finish(bool ok,string reason){if(finished)return;finished=true;passed=ok;bool cleanup=false;try{scenario?.Dispose();cleanup=true;}catch(Exception e){passed=false;reason="cleanup_failed";Log(new{kind="cleanup_error",error=e.ToString()});}finally{try{Log(new{kind="result",passed,reason,seconds=clock.Elapsed.TotalSeconds,actors,cleanupVerified=cleanup,cleanupMeaning="Dispose completed without exception, not independent resource-release audit",updateFailures=GameManager.Project?.FindSubsystem<SubsystemUpdate>(false)?.UpdateFailureCount});}finally{Window.Close();}}}
}
