  for(int i=0;i<ps.Length;i++)senses.Bind(Guid.NewGuid(),ps[i]);var u=p.Project.FindSubsystem<SubsystemUpdate>(true);u.AddUpdateable(senses);terrain=p.Project.FindSubsystem<SubsystemTerrain>(true);backend=new(terrain,p.Project.FindSubsystem<SubsystemSpawn>(true));interests=new(senses.Registry,backend,new InterestRadii(32,48));interests.Sync();foreach(var actor in ps)terrain.TerrainUpdater.RemoveUpdateLocation(actor.PlayerData.PlayerIndex);}
