 object NativeState()=>new {position=new[]{p.ComponentBody.Position.X,p.ComponentBody.Position.Y,p.ComponentBody.Position.Z},velocity=new[]{p.ComponentBody.Velocity.X,p.ComponentBody.Velocity.Y,p.ComponentBody.Velocity.Z},grounded=p.ComponentBody.StandingOnValue.HasValue,parented=p.ComponentBody.ParentBody is not null,embedded=p.ComponentBody.IsEmbeddedInIce,stun=p.ComponentLocomotion.StunTime,disabled=p.ComponentLocomotion.DisableInputMovement,lookSpeed=p.ComponentLocomotion.LookSpeed,health=p.ComponentHealth.Health};
 object[] ChunkStates(){var pos=p.ComponentBody.Position;var list=new List<object>();for(int a=(Terrain.ToCell(pos.X-5)>>4);a<=(Terrain.ToCell(pos.X+5)>>4);a++)for(int c=(Terrain.ToCell(pos.Z-5)>>4);c<=(Terrain.ToCell(pos.Z+5)>>4);c++){var chunk=terrain.Terrain.GetChunkAtCell(a*16,c*16);list.Add(new{chunkX=a,chunkZ=c,state=chunk?.State.ToString()??"missing",distanceToActorCenters=players.Select(q=>Vector2.Distance(new Vector2(a*16+8,c*16+8),q.ComponentBody.Position.XZ)).ToArray()});}return list.ToArray();}
 bool AllScanRegionsReady(){bool loaded=true;var missing=new List<object>();for(int i=0;i<players.Length;i++){var pos=players[i].ComponentBody.Position;for(int a=Terrain.ToCell(pos.X-5)>>4;a<=Terrain.ToCell(pos.X+5)>>4;a++)for(int c=Terrain.ToCell(pos.Z-5)>>4;c<=Terrain.ToCell(pos.Z+5)>>4;c++){var state=terrain.Terrain.GetChunkAtCell(a*16,c*16)?.State;if(state!=TerrainChunkState.Valid){loaded=false;missing.Add(new{actor=i,chunkX=a,chunkZ=c,state=state?.ToString()??"missing"});}}}
 if(loaded)return true;if(waitingStage!=9){waitingStage=9;waitingSince=clock.Elapsed.TotalSeconds;Gate.Log(new{kind="cost_await_loaded",missing});}if(clock.Elapsed.TotalSeconds-waitingSince>8){Gate.Log(new{kind="cost_loaded_timeout",missing});throw new TimeoutException("all actor observation regions not ready for benchmark");}return false;}
 static bool HasScanWork(JsonElement o){var v=o.GetProperty("coverage").GetProperty("scanStatistics");return v.GetProperty("knownCells").GetInt32()>0&&v.GetProperty("lineOfSightChecks").GetInt32()>0&&v.GetProperty("voxelReads").GetInt32()>0;}
 bool Ready(bool settle=false){var pos=p.ComponentBody.Position;bool loaded=true;for(int a=Terrain.ToCell(pos.X-5)>>4;a<=Terrain.ToCell(pos.X+5)>>4;a++)for(int c=Terrain.ToCell(pos.Z-5)>>4;c<=Terrain.ToCell(pos.Z+5)>>4;c++)loaded&=terrain.Terrain.GetChunkAtCell(a*16,c*16)?.State==TerrainChunkState.Valid;
 bool stable=!settle||(p.ComponentBody.StandingOnValue.HasValue&&p.ComponentBody.Velocity.Length()<.1f&&p.ComponentBody.ParentBody is null&&!p.ComponentBody.IsEmbeddedInIce&&p.ComponentLocomotion.StunTime<=0&&!p.ComponentLocomotion.DisableInputMovement);
 if(loaded&&stable){if(waitingStage==stage)Gate.Log(new{kind="native_ready",stage,waitSeconds=clock.Elapsed.TotalSeconds-waitingSince,state=NativeState(),chunks=ChunkStates()});waitingStage=int.MinValue;return true;}
 if(waitingStage!=stage){waitingStage=stage;waitingSince=clock.Elapsed.TotalSeconds;Gate.Log(new{kind="await_native_ready",stage,loaded,stable,state=NativeState(),chunks=ChunkStates(),activityCenters=players.Select(q=>new[]{q.ComponentBody.Position.X,q.ComponentBody.Position.Y,q.ComponentBody.Position.Z}).ToArray(),fullReady=32,content=48});}if(clock.Elapsed.TotalSeconds-waitingSince>8){Gate.Log(new{kind="native_ready_timeout",stage,loaded,stable,state=NativeState(),chunks=ChunkStates()});throw new TimeoutException("native prerequisite did not recover");}return false;
 }
