 public void Update(float dt){if(Done)return;try{interests.Sync();if(clock.Elapsed.TotalSeconds>50)throw new TimeoutException("scenario budget");
  if(stage==-3){if(clock.Elapsed.TotalSeconds>10)throw new TimeoutException("native mount animation did not settle");if(players.Any(q=>q.Entity.FindComponent<ComponentRider>(true).m_isAnimating))return;
