  if(stage==-2){if(clock.Elapsed.TotalSeconds-dismountStarted>8)throw new TimeoutException("fixture dismount timeout");if(actions.Any(a=>a.IsActionRunning))return;for(int i=0;i<players.Length;i++){Gate.Log(new{kind="fixture_dismount_terminal",actor=i,result=dismountRuns[i].Result,parented=players[i].ComponentBody.ParentBody is not null});Check(dismountRuns[i].Result.Status==AtomicActionStatus.Succeeded&&players[i].ComponentBody.ParentBody is null,"native fixture dismount succeeded without clearing parent");}stage=0;return;}
