   var wood=blocks.SingleOrDefault(b=>At(b,x+3,y+1,z-1));Check(wood.ValueKind==JsonValueKind.Object,"first off-axis block visible");Check(blocks.Any(b=>At(b,x+3,y+1,z+1)),"second off-axis block same snapshot");Check(!blocks.Any(b=>At(b,x-3,y+1,z)),"behind actor block absent");Check(!blocks.Any(b=>At(b,x+6,y+1,z)),"outside bounded scan absent");
