   var limited=Observe(blockLimit:1);var coverage=limited.GetProperty("coverage");Check(Blocks(limited).Length==1&&coverage.GetProperty("returnedBlocks").GetInt32()==1&&coverage.GetProperty("omittedBlocks").GetInt32()>0,"limit one reports actual omitted blocks");
