   digCell=new(x+1,y,z);Set(digCell.X,digCell.Y,digCell.Z,DirtBlock.Index);var target=new Vector3(digCell.X+.5f,digCell.Y+.5f,digCell.Z+.5f);var delta=target-p.ComponentCreatureModel.EyePosition;float pitch=MathF.Asin(delta.Y/delta.Length())*180/MathF.PI;aim=actions[0].Start(new FaceTowards(target,4,pitch));Gate.Log(new{kind="explicit_dig_fixture",cell=new[]{digCell.X,digCell.Y,digCell.Z},value=DirtBlock.Index,inventoryInjection=false});stage=7;return;}
